using System.Collections.Generic;
using UnityEngine;
using MutationChess.UI;  namespace MutationChess.Core
{  /// <summary>  ///  ///  /// ?? CardData.GetAllCardNames() Corrupt  ///  /// </summary>  [CreateAssetMenu(fileName = "CorruptAddCardEffect", menuName = "MutationChess/Relic Effects/Corrupt Add Card")]  public class CorruptAddCardEffect : CardEffect  {  [Header("")]  [Tooltip("")]  [Min(1)]  public int count = 1;  [Tooltip("Boss")]  public int bossExtraCount = 1;  public override void Execute(CombatContext context)  {  AddCorruptCardsToHand();  }  public override void Execute(EffectContext context)  {  AddCorruptCardsToHand();  }  private void AddCorruptCardsToHand()  {  var handManager = HandManager.Instance;  if (handManager == null)  {  GameLogger.LogError("[CorruptAddCard] HandManager ");  return;  }  List<CardName> candidates = new List<CardName>();  foreach (var name in CardData.GetAllCardNames())  {  var template = CardData.GetTemplate(name);  if (template != null && template.tags != null && template.tags.Contains(CardTag.Corrupt))  {  candidates.Add(name);  }  }  if (candidates.Count == 0)  {  GameLogger.LogWarning("[CorruptAddCard] ");  return;  }  int totalCount = count + (ConversionModifier.BossCorruptLiverActive ? bossExtraCount : 0);  for (int i = 0; i < totalCount; i++)  {  CardName pick = candidates[Random.Range(0, candidates.Count)];  Card newCard = CardData.CreateCard(pick);  if (newCard != null)  {  handManager.AddCardToHand(newCard);  GameLogger.Log($"[CorruptAddCard] : {newCard.cardName}");  }  }  }  }
}
